commit 7e4a2f39efda621f0f4ffe29f392f62ed396e4b4
Author: Willy Tarreau <w@1wt.eu>
Date:   Fri May 2 15:46:18 2025 +0200

    BUG/MINOR: tools: do not create an empty arg from trailing spaces

    Trailing spaces on the lines of the config file create an empty arg
    which makes it complicated to detect really empty args. Let's first
    address this. Note that it is not user-visible but prevents from
    fixing user-visible issues. No backport is needed.

    The initial issue was introduced with this fix that already tried to
    address it:

        8a6767d266 ("BUG/MINOR: config: don't count trailing spaces as empty arg (v2)")

    The current patch properly addresses leading and trailing spaces by
    only counting arguments if non-lws chars were found on the line. LWS
    do not cause a transition to a new arg anymore but they complete the
    current one. The whole new code relies on a state machine to detect
    when to create an arg (!in_arg->in_arg), and when to close the current
    arg. A special care was taken for word expansion in the form of
    "${ARGS[*]}" which still continue to emit individual arguments past
    the first LWS. This example works fine:

        ARGS="100 check inter 1000"
        server name 192.168.1."${ARGS[*]}"

    It properly results in 6 args:

        "server", "name", "192.168.1.100", "check", "inter", "1000"

    This fix should not have any visible user impact and is a bit tricky,
    so it's best not to backport it, at least for a while.

    Co-authored-by: Valentine Krasnobaeva <vkrasnobaeva@haproxy.com>

diff --git a/src/tools.c b/src/tools.c
index 6c4dd7dfa..85b958655 100644
--- a/src/tools.c
+++ b/src/tools.c
@@ -6178,10 +6178,13 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
        size_t outmax = *outlen;
        int argsmax = *nbargs - 1;
        size_t outpos = 0;
+       size_t arg_start = 0; // copy of outpos before EMIT_CHAR().
        int squote = 0;
        int dquote = 0;
        int arg = 0;
        uint32_t err = 0;
+       int in_arg = 0;
+       int prev_in_arg = 0;

        *nbargs = 0;
        *outlen = 0;
@@ -6191,12 +6194,15 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                args[arg] = out;

        while (1) {
+               prev_in_arg = in_arg;
+               arg_start = outpos;
+
                if (*in >= '-' && *in != '\\') {
+                       in_arg = 1;
                        /* speedup: directly send all regular chars starting
                         * with '-', '.', '/', alnum etc...
                         */
                        EMIT_CHAR(*in++);
-                       continue;
                }
                else if (*in == '\0' || *in == '\n' || *in == '\r') {
                        /* end of line */
@@ -6207,6 +6213,7 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                        break;
                }
                else if (*in == '"' && !squote && (opts & PARSE_OPT_DQUOTE)) {  /* double quote outside single quotes */
+                       in_arg = 1;
                        if (dquote) {
                                dquote = 0;
                                quote = NULL;
@@ -6216,9 +6223,9 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                                quote = in;
                        }
                        in++;
-                       continue;
                }
                else if (*in == '\'' && !dquote && (opts & PARSE_OPT_SQUOTE)) { /* single quote outside double quotes */
+                       in_arg = 1;
                        if (squote) {
                                squote = 0;
                                quote = NULL;
@@ -6228,7 +6235,6 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                                quote = in;
                        }
                        in++;
-                       continue;
                }
                else if (*in == '\\' && !squote && (opts & PARSE_OPT_BKSLASH)) {
                        /* first, we'll replace \\, \<space>, \#, \r, \n, \t, \xXX with their
@@ -6237,6 +6243,7 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                         */
                        char tosend = *in;

+                       in_arg = 1;
                        switch (in[1]) {
                        case ' ':
                        case '\\':
@@ -6313,14 +6320,9 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                }
                else if (isspace((unsigned char)*in) && !squote && !dquote) {
                        /* a non-escaped space is an argument separator */
+                       in_arg = 0;
                        while (isspace((unsigned char)*in))
                                in++;
-                       EMIT_CHAR(0);
-                       arg++;
-                       if (arg < argsmax)
-                               args[arg] = out + outpos;
-                       else
-                               err |= PARSE_ERR_TOOMANY;

commit 1f51f1c816b43cbfd6526bb17fe1bf9995fc083a
Author: Willy Tarreau <w@1wt.eu>
Date:   Mon May 5 17:58:04 2025 +0200

    BUG/MINOR: tools: make parseline report the required space for the trailing 0

    The fix in commit 09a325a4de ("BUG/MINOR: tools: always terminate empty
    lines") is insufficient. While it properly addresses the lack of trailing
    zero, it doesn't account for it in the returned outlen that is used to
    allocate a larger line. This happens at boot if the very first line of
    the test file is exactly a sharp with nothing else. In this case it will
    return a length 0 and the caller (parse_cfg()) will try to re-allocate an
    entry of size zero and will fail, bailing out a lack of memory. This time
    it should really be OK.

    It doesn't need to be backported, unless the patch above would be.

diff --git a/src/tools.c b/src/tools.c
index fbb4c4781..73335d21e 100644
--- a/src/tools.c
+++ b/src/tools.c
@@ -6504,13 +6504,13 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                goto leave;
        }
  leave:
-       *nbargs = arg;
-       *outlen = outpos;
-
        /* make sure empty lines are terminated */
        if (!arg)
                EMIT_CHAR(0);

+       *nbargs = arg;
+       *outlen = outpos;
+
        /* empty all trailing args by making them point to the trailing zero,
         * at least the last one in any case.
         */

commit 10e6d0bd5702586a11daf8bd320713e0b501e37d
Author: Willy Tarreau <w@1wt.eu>
Date:   Wed May 7 07:22:24 2025 +0200

    BUG/MINOR: tools: only fill first empty arg when not out of range

    In commit 3f2c8af313 ("MINOR: tools: make parse_line() provide hints
    about empty args") we've added the ability to record the position of
    the first empty arg in parse_line(), but that check requires to
    access the args[] array for the current arg, which is not valid in
    case we stopped on too large an argument count. Let's just check the
    arg's validity before doing so.

    This was reported by OSS Fuzz:
      https://issues.oss-fuzz.com/issues/415850462

    No backport is needed since this was in the latest dev branch.

diff --git a/src/tools.c b/src/tools.c
index 73335d21e..313396823 100644
--- a/src/tools.c
+++ b/src/tools.c
@@ -6439,7 +6439,7 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                                                        err |= PARSE_ERR_TOOMANY;
                                        }
                                        if (prev_in_arg && !in_arg) {
-                                               if (!empty_arg_ptr && args[arg] == out + arg_start)
+                                               if (!empty_arg_ptr && arg < argsmax && args[arg] == out + arg_start)
                                                        empty_arg_ptr = begin_new_arg;
                                                EMIT_CHAR(0);
                                                arg++;
@@ -6481,7 +6481,7 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg
                }

                if (prev_in_arg && !in_arg) {
-                       if (!empty_arg_ptr && args[arg] == out + arg_start)
+                       if (!empty_arg_ptr && arg < argsmax && args[arg] == out + arg_start)
                                empty_arg_ptr = begin_new_arg;
                        EMIT_CHAR(0);
                        arg++;
@@ -6490,7 +6490,7 @@ uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbarg

        /* end of output string */
        if (in_arg) {
-               if (!empty_arg_ptr && args[arg] == out + arg_start)
+               if (!empty_arg_ptr && arg < argsmax && args[arg] == out + arg_start)
                        empty_arg_ptr = begin_new_arg;
                EMIT_CHAR(0);
                arg++;

